size_t shared = 0;
if (*counter_ >= restart_interval) {
    restarts_->push_back(buffer_->size());
    *counter_ = 0;
} else {
    // See how much sharing to do with previous string
    const size_t min_length = std::min(last_key_->size(), key.size());
    while ((shared < min_length) && (last_key_->data()[shared] == key.data()[shared])) {
        shared++;
    }
}
const size_t non_shared = key.size() - shared;
// Add "<shared><non_shared><value_size>" to buffer_
std::string shared_str;
std::string non_shared_str;
std::string value_size_str;
leveldb::PutVarint32(&shared_str, shared);
leveldb::PutVarint32(&non_shared_str, non_shared);
leveldb::PutVarint32(&value_size_str, value.size());
buffer_->append(shared_str);
buffer_->append(non_shared_str);
buffer_->append(value_size_str);
// Add string delta to buffer_ followed by value
buffer_->append(key.data() + shared, non_shared);
buffer_->append(value.data(), value.size());
// Update state
last_key_->resize(shared);
last_key_->append(key.data() + shared, non_shared);
assert(leveldb::Slice(*last_key_) == key);
(*counter_)++;

